{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'
import { parse } from './parse.js'
import { count } from './count.js'

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'rounds' && args[0] !== 'tally')) {
  process.stderr.write('error: usage: cli.js rounds|tally\n')
  process.exit(2)
}
let election
try {
  election = parse(readFileSync(0, 'utf8'))
} catch (e) {
  if (e && e.userMessage) {
    process.stderr.write(e.userMessage + '\n')
    process.exit(2)
  }
  throw e
}
const { rounds, winner } = count(election)
let out = ''
if (args[0] === 'rounds') {
  rounds.forEach((r, i) => {
    out += `round ${i + 1}: ${r.list.map(([n, v]) => `${n}=${v}`).join(' ')} exhausted=${r.exhausted}\n`
    if (r.eliminated !== undefined) out += `eliminated ${r.eliminated}\n`
  })
} else {
  out += `rounds ${rounds.length}\n`
}
out += winner === null ? 'no winner\n' : `winner ${winner}\n`
process.stdout.write(out)
EOF
cat > src/parse.js <<'EOF'
const fail = (msg) => { throw Object.assign(new Error(msg), { userMessage: msg }) }

export function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  let candidates = null
  let seenBallot = false
  const ballots = []
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const n = i + 1
    const w = line.split(/\s+/)
    if (w[0] === 'candidates') {
      if (candidates !== null || seenBallot) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
      if (w.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
      const seen = new Set()
      for (const name of w.slice(1)) {
        if (!/^[A-Za-z0-9_-]+$/.test(name)) fail(`error: line ${n}: invalid candidate name ${name}`)
        if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is declared twice`)
        seen.add(name)
      }
      candidates = w.slice(1)
    } else if (w[0] === 'ballot') {
      if (candidates === null) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
      seenBallot = true
      if (w.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
      if (!/^[1-9][0-9]*$/.test(w[1])) fail(`error: line ${n}: count must be a positive integer`)
      const seen = new Set()
      for (const name of w.slice(2)) {
        if (!candidates.includes(name)) fail(`error: line ${n}: unknown candidate ${name}`)
        if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count: BigInt(w[1]), prefs: w.slice(2) })
    } else {
      fail(`error: line ${n}: unknown directive ${w[0]}`)
    }
  }
  if (candidates === null) fail('error: no candidates')
  return { candidates, ballots }
}
EOF
cat > src/count.js <<'EOF'
const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

export function count({ candidates, ballots }) {
  const continuing = new Set(candidates)
  const history = []
  const rounds = []
  for (;;) {
    const votes = new Map([...continuing].map((c) => [c, 0n]))
    let active = 0n
    for (const b of ballots) {
      const c = b.prefs.find((p) => continuing.has(p))
      if (c !== undefined) { votes.set(c, votes.get(c) + b.count); active += b.count }
    }
    let total = 0n
    for (const b of ballots) total += b.count
    history.push(votes)
    const list = [...votes.entries()].sort((a, b) => cmp(b[1], a[1]) || cmp(a[0], b[0]))
      .map(([n, v]) => [n, v.toString()])
    const round = { list, exhausted: (total - active).toString() }
    rounds.push(round)
    if (active === 0n) return { rounds, winner: null }
    for (const [n, v] of votes) if (v * 2n > active) return { rounds, winner: n }
    let min = null
    for (const v of votes.values()) if (min === null || v < min) min = v
    let tied = [...votes].filter(([, v]) => v === min).map(([n]) => n)
    while (tied.length > 1) {
      let reduced = false
      for (const h of history) {
        const vs = tied.map((n) => h.get(n))
        const m = vs.reduce((a, b) => (b < a ? b : a))
        if (vs.some((v) => v !== m)) {
          tied = tied.filter((n) => h.get(n) === m)
          reduced = true
          break
        }
      }
      if (!reduced) break
    }
    tied.sort(cmp)
    const out = tied[tied.length - 1]
    round.eliminated = out
    continuing.delete(out)
  }
}
EOF
