{"command":"cat > src/cli.js <<'EOF'
const MODES = ['normalize', 'resolve']

class Fail extends Error {}

function parse(s) {
  const m = /^(?:([^:/?#]+):)?(?:\/\/([^/?#]*))?([^?#]*)(?:\?([^#]*))?(?:#([\s\S]*))?$/.exec(s)
  const r = { scheme: m[1], path: m[3], query: m[4], fragment: m[5] }
  if (m[2] !== undefined) {
    const a = m[2]
    const at = a.lastIndexOf('@')
    const userinfo = at >= 0 ? a.slice(0, at) : undefined
    const hp = a.slice(at + 1)
    const colon = hp.indexOf(':', hp.lastIndexOf(']') + 1)
    r.userinfo = userinfo
    r.host = colon >= 0 ? hp.slice(0, colon) : hp
    r.port = colon >= 0 ? hp.slice(colon + 1) : undefined
    r.hasAuth = true
  }
  return r
}

function lowerAscii(s) {
  return s.replace(/[A-Z]/g, (c) => c.toLowerCase())
}

function pct(s) {
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const H = h.toUpperCase()
    const c = String.fromCharCode(parseInt(H, 16))
    return /[A-Za-z0-9\-._~]/.test(c) ? c : '%' + H
  })
}

function check(r) {
  const bad = /%(?![0-9A-Fa-f]{2})/
  for (const k of ['path', 'userinfo', 'host', 'query', 'fragment']) {
    if (r[k] !== undefined && bad.test(r[k])) throw new Fail(`the ${k} has a truncated percent-encoding`)
  }
}

function removeDots(p) {
  let inp = p
  let out = ''
  while (inp.length) {
    if (inp.startsWith('../')) inp = inp.slice(3)
    else if (inp.startsWith('./')) inp = inp.slice(2)
    else if (inp.startsWith('/./')) inp = inp.slice(2)
    else if (inp === '/.') inp = '/'
    else if (inp.startsWith('/../') || inp === '/..') {
      inp = inp === '/..' ? '/' : inp.slice(3)
      out = out.slice(0, Math.max(0, out.lastIndexOf('/')))
    } else if (inp === '.' || inp === '..') inp = ''
    else {
      const i = inp.indexOf('/', 1)
      const seg = i < 0 ? inp : inp.slice(0, i)
      out += seg
      inp = inp.slice(seg.length)
    }
  }
  return out
}

const DEFAULTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

function serialize(r) {
  let s = ''
  if (r.scheme !== undefined) s += r.scheme + ':'
  if (r.hasAuth) {
    s += '//'
    if (r.userinfo !== undefined) s += r.userinfo + '@'
    s += r.host
    if (r.port !== undefined) s += ':' + r.port
  }
  s += r.path
  if (r.query !== undefined) s += '?' + r.query
  if (r.fragment !== undefined) s += '#' + r.fragment
  return s
}

function normalize(r) {
  check(r)
  const o = { ...r }
  if (o.scheme !== undefined) o.scheme = lowerAscii(o.scheme)
  for (const k of ['userinfo', 'host', 'port', 'path', 'query', 'fragment']) {
    if (o[k] !== undefined) o[k] = pct(o[k])
  }
  if (o.hasAuth) {
    o.host = lowerAscii(o.host)
    if (o.port === '' || (o.scheme in DEFAULTS && o.port === DEFAULTS[o.scheme])) o.port = undefined
  }
  o.path = removeDots(o.path)
  if (o.hasAuth && o.path === '') o.path = '/'
  return serialize(o)
}

function resolve(base, ref) {
  if (base.scheme === undefined) throw new Fail('the base has no scheme')
  if (ref.scheme !== undefined) return { ...ref, path: removeDots(ref.path) }
  const t = { scheme: base.scheme }
  const auth = (a) => {
    t.hasAuth = a.hasAuth
    t.userinfo = a.userinfo
    t.host = a.host
    t.port = a.port
  }
  if (ref.hasAuth) {
    auth(ref)
    t.path = removeDots(ref.path)
    t.query = ref.query
  } else {
    auth(base)
    if (ref.path === '') {
      t.path = base.path
      t.query = ref.query !== undefined ? ref.query : base.query
    } else {
      if (ref.path.startsWith('/')) t.path = removeDots(ref.path)
      else {
        let merged
        if (base.hasAuth && base.path === '') merged = '/' + ref.path
        else {
          const i = base.path.lastIndexOf('/')
          merged = i >= 0 ? base.path.slice(0, i + 1) + ref.path : ref.path
        }
        t.path = removeDots(merged)
      }
      t.query = ref.query
    }
  }
  t.fragment = ref.fragment
  return t
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || !MODES.includes(args[0])) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
  }
  const mode = args[0]
  const text = require_stdin()
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const out = []
  try {
    lines.forEach((line, idx) => {
      try {
        if (mode === 'normalize') out.push(normalize(parse(line)))
        else {
          const sp = line.indexOf(' ')
          if (sp < 0) throw new Fail('expected a base and a reference')
          const base = parse(line.slice(0, sp))
          const ref = parse(line.slice(sp + 1))
          if (base.scheme === undefined) throw new Fail('the base has no scheme')
          out.push(normalize(resolve(base, ref)))
        }
      } catch (e) {
        if (e instanceof Fail) throw new Fail(`line ${idx + 1}: ${e.message}`)
        throw e
      }
    })
  } catch (e) {
    if (!(e instanceof Fail)) throw e
    process.stderr.write(`error: ${e.message}\n`)
    process.exit(2)
  }
  process.stdout.write(out.map((l) => l + '\n').join(''))
}

function require_stdin() {
  return process.getBuiltinModule('fs').readFileSync(0, 'utf8')
}

main()
EOF
