  const bad = /%(?![0-9A-Fa-f]{2})/
  for (const k of ['path', 'userinfo', 'host', 'query', 'fragment']) {
    if (r[k] !== undefined && bad.test(r[k])) throw new Fail(`the ${k} has a truncated percent-encoding`)
  }
}

function removeDots(p) {
  let inp = p
  let out = ''
  while (inp.length) {
    if (inp.startsWith('../')) inp = inp.slice(3)
    else if (inp.startsWith('./')) inp = inp.slice(2)
    else if (inp.startsWith('/./')) inp = inp.slice(2)
    else if (inp === '/.') inp = '/'
    else if (inp.startsWith('/../') || inp === '/..') {
      inp = inp === '/..' ? '/' : inp.slice(3)
      out = out.slice(0, Math.max(0, out.lastIndexOf('/')))
    } else if (inp === '.' || inp === '..') inp = ''
    else {
      const i = inp.indexOf('/', 1)
      const seg = i < 0 ? inp : inp.slice(0, i)
      out += seg
      inp = inp.slice(seg.length)
    }
  }
  return out
}

const DEFAULTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

function serialize(r) {
  let s = ''
  if (r.scheme !== undefined) s += r.scheme + ':'
  if (r.hasAuth) {
    s += '//'
    if (r.userinfo !== undefined) s += r.userinfo + '@'
    s += r.host
    if (r.port !== undefined) s += ':' + r.port
  }
  s += r.path
  if (r.query !== undefined) s += '?' + r.query
  if (r.fragment !== undefined) s += '#' + r.fragment
  return s
}

function normalize(r) {
  check(r)
  const o = { ...r }
  if (o.scheme !== undefined) o.scheme = lowerAscii(o.scheme)
  for (const k of ['userinfo', 'host', 'port', 'path', 'query', 'fragment']) {
    if (o[k] !== undefined) o[k] = pct(o[k])
