  if (o.hasAuth && o.path === '') o.path = '/'
  return serialize(o)
}

function resolve(base, ref) {
  if (base.scheme === undefined) throw new Fail('the base has no scheme')
  if (ref.scheme !== undefined) return { ...ref, path: removeDots(ref.path) }
  const t = { scheme: base.scheme }
  const auth = (a) => {
    t.hasAuth = a.hasAuth
    t.userinfo = a.userinfo
    t.host = a.host
    t.port = a.port
  }
  if (ref.hasAuth) {
    auth(ref)
    t.path = removeDots(ref.path)
    t.query = ref.query
  } else {
    auth(base)
    if (ref.path === '') {
      t.path = base.path
      t.query = ref.query !== undefined ? ref.query : base.query
    } else {
      if (ref.path.startsWith('/')) t.path = removeDots(ref.path)
      else {
