export class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
    this.reason = reason
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const PUNCT1 = new Set('+-*/%=<>!(){}[],;.'.split(''))
const isLetter = (c) => c !== undefined && /^[A-Za-z_]$/.test(c)
const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isAlnum = (c) => isLetter(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isOct = (c) => c !== undefined && c >= '0' && c <= '7'
const isBin = (c) => c === '0' || c === '1'

export function scan(text) {
  const s = Array.from(text)
  const n = s.length
  const lines = new Array(n + 1)
  const cols = new Array(n + 1)
  let l = 1
  let c = 1
  for (let k = 0; k < n; k++) {
    lines[k] = l
    cols[k] = c
    if (s[k] === '\n') { l++; c = 1 }
    else if (s[k] === '\t') c = Math.floor((c - 1) / 4) * 4 + 5
    else c++
  }
  lines[n] = l
  cols[n] = c
  const err = (k, reason) => new ScanError(lines[k], cols[k], reason)
  const toks = []
  const push = (k, kind, body) => toks.push({ line: lines[k], col: cols[k], kind, body })

  // Consume a run of digits satisfying pred starting at j; returns the end index.
  const run = (j, pred) => {
    if (!pred(s[j])) return j
    j++
    for (;;) {
      if (pred(s[j])) j++
      else if (s[j] === '_' && pred(s[j - 1]) && pred(s[j + 1])) j++
      else break
    }
    return j
  }

  let i = 0
  while (i < n) {
    const ch = s[i]
    if (ch === ' ' || ch === '\t' || ch === '\r' || ch === '\n') { i++; continue }
    if (ch === '/' && s[i + 1] === '/') {
      while (i < n && s[i] !== '\n') i++
      continue
    }
    if (ch === '/' && s[i + 1] === '*') {
      const start = i
      let depth = 1
      i += 2
      while (i < n && depth > 0) {
        if (s[i] === '/' && s[i + 1] === '*') { depth++; i += 2 }
        else if (s[i] === '*' && s[i + 1] === '/') { depth--; i += 2 }
        else i++
      }
      if (depth > 0) throw err(start, 'unterminated block comment')
      continue
    }
    if (ch === 'r' && s[i + 1] === '"') {
      let j = i + 2
      while (j < n && s[j] !== '"') j++
      if (j >= n) throw err(i, 'unterminated string')
      push(i, 'rawstring', JSON.stringify(s.slice(i + 2, j).join('')))
      i = j + 1
      continue
    }
    if (isLetter(ch)) {
      let j = i + 1
      while (isAlnum(s[j])) j++
      const w = s.slice(i, j).join('')
      push(i, KEYWORDS.has(w) ? 'keyword' : 'ident', w)
      i = j
      continue
    }
    if (isDigit(ch)) {
      let j = i + 1
