#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */
import { readFileSync } from 'node:fs'

class Fail extends Error {
  constructor(msg, code = 2) {
    super(msg)
    this.code = code
  }
}

const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)
const NAME = /^[A-Za-z0-9_.-]+$/

function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const costs = new Map()
  const deps = []
  lines.forEach((raw, i) => {
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const w = line.split(/\s+/)
    const n = i + 1
    if (w[0] === 'task') {
      if (w.length !== 3) throw new Fail(`error: line ${n}: expected task <name> <cost>`)
      if (!NAME.test(w[1])) throw new Fail(`error: line ${n}: invalid task name ${w[1]}`)
      if (!/^[0-9]+$/.test(w[2])) throw new Fail(`error: line ${n}: cost must be a non-negative integer`)
      if (costs.has(w[1])) throw new Fail(`error: line ${n}: task ${w[1]} is declared twice`)
      costs.set(w[1], BigInt(w[2]))
    } else if (w[0] === 'dep') {
      if (w.length < 3) throw new Fail(`error: line ${n}: expected dep <name> <dependency>...`)
      for (const name of w.slice(1)) {
        if (!NAME.test(name)) throw new Fail(`error: line ${n}: invalid task name ${name}`)
      }
      deps.push(w.slice(1))
    } else {
      throw new Fail(`error: line ${n}: unknown directive ${w[0]}`)
    }
  })
  const dmap = new Map([...costs.keys()].map((k) => [k, new Set()]))
  for (const d of deps) {
    for (const name of d) if (!costs.has(name)) throw new Fail(`error: unknown task ${name}`)
    for (const x of d.slice(1)) dmap.get(d[0]).add(x)
  }
  const names = [...costs.keys()].sort(cmp)
  const sorted = new Map(names.map((k) => [k, [...dmap.get(k)].sort(cmp)]))
  return { costs, deps: sorted, names }
}

function checkCycle({ names, deps }) {
  const state = new Map()
  const stack = []
  const visit = (u) => {
    state.set(u, 1)
    stack.push(u)
    for (const v of deps.get(u)) {
      const s = state.get(v)
      if (s === 1) {
        const cyc = stack.slice(stack.indexOf(v))
        cyc.push(v)
        throw new Fail(`error: cycle: ${cyc.join(' -> ')}`, 3)
      }
      if (!s) visit(v)
    }
    stack.pop()
    state.set(u, 2)
  }
  for (const u of names) if (!state.get(u)) visit(u)
}

function times({ names, deps, costs }) {
  const start = new Map()
  const finish = new Map()
  const depth = new Map()
  const go = (u) => {
    if (finish.has(u)) return
    let s = 0n
    let d = 0
    for (const v of deps.get(u)) {
      go(v)
      if (finish.get(v) > s) s = finish.get(v)
      d = Math.max(d, depth.get(v) + 1)
    }
    start.set(u, s)
    finish.set(u, s + costs.get(u))
    depth.set(u, d)
  }
  for (const u of names) go(u)
  let total = 0n
  for (const f of finish.values()) if (f > total) total = f
  return { start, finish, depth, total }
}

function pack(g, workers) {
  const { names, deps, costs } = g
  const prio = new Map()
  const rev = new Map(names.map((k) => [k, []]))
  for (const u of names) for (const v of deps.get(u)) rev.get(v).push(u)
  const pr = (u) => {
    if (prio.has(u)) return prio.get(u)
    let m = 0n
    for (const x of rev.get(u)) {
      const p = pr(x)
      if (p > m) m = p
    }
    prio.set(u, m + costs.get(u))
    return prio.get(u)
  }
  names.forEach(pr)
  const order = [...names].sort((a, b) => (prio.get(a) === prio.get(b) ? cmp(a, b) : prio.get(a) > prio.get(b) ? -1 : 1))
  const done = new Map()
  const freeAt = Array(workers).fill(0n)
  const runs = Array.from({ length: workers }, () => [])
  let t = 0n
  let left = names.length
  let makespan = 0n
  while (left > 0) {
    for (;;) {
      const w = freeAt.findIndex((f) => f <= t)
      if (w < 0) break
      const task = order.find((u) => !done.has(u) && deps.get(u).every((d) => done.has(d) && done.get(d) <= t))
      if (task === undefined) break
      const f = t + costs.get(task)
      done.set(task, f)
      freeAt[w] = f
      runs[w].push(` ${task}@${t}-${f}`)
      if (f > makespan) makespan = f
      left--
    }
    if (left === 0) break
    let next = null
    for (const f of freeAt) if (f > t && (next === null || f < next)) next = f
    for (const f of done.values()) if (f > t && (next === null || f < next)) next = f
    if (next === null) break
    t = next
  }
  return runs.map((r, i) => `worker ${i}:${r.join('')}\n`).join('') + `makespan ${makespan}\n`
}

function main() {
  const a = process.argv.slice(2)
  const ok = (a.length === 1 && (a[0] === 'waves' || a[0] === 'explain')) || (a.length === 2 && a[0] === 'pack')
  if (!ok) throw new Fail('error: usage: cli.js waves|explain|pack <workers>')
  if (a[0] === 'pack' && !/^[1-9][0-9]*$/.test(a[1])) throw new Fail('error: workers must be a positive integer')
  const g = parse(readFileSync(0, 'utf8'))
  checkCycle(g)
  let out = ''
  if (a[0] === 'pack') {
    out = pack(g, Number(a[1]))
  } else {
    const r = times(g)
    if (a[0] === 'waves') {
      const waves = []
      for (const u of g.names) (waves[r.depth.get(u)] ??= []).push(u)
      waves.forEach((ws, k) => (out += `wave ${k}: ${ws.join(' ')}\n`))
    } else {
      for (const u of g.names) out += `${u} start=${r.start.get(u)} finish=${r.finish.get(u)} depth=${r.depth.get(u)}\n`
    }
    out += `total ${r.total}\n`
  }
  process.stdout.write(out)
}

try {
  main()
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(e.message + '\n')
  process.exitCode = e.code
}
