      d = Math.max(d, depth.get(v) + 1)
    }
    start.set(u, s)
    finish.set(u, s + costs.get(u))
    depth.set(u, d)
  }
  for (const u of names) go(u)
  let total = 0n
  for (const f of finish.values()) if (f > total) total = f
  return { start, finish, depth, total }
}

function pack(g, workers) {
  const { names, deps, costs } = g
  const prio = new Map()
  const rev = new Map(names.map((k) => [k, []]))
  for (const u of names) for (const v of deps.get(u)) rev.get(v).push(u)
  const pr = (u) => {
    if (prio.has(u)) return prio.get(u)
    let m = 0n
    for (const x of rev.get(u)) {
      const p = pr(x)
      if (p > m) m = p
    }
    prio.set(u, m + costs.get(u))
    return prio.get(u)
  }
  names.forEach(pr)
  const order = [...names].sort((a, b) => (prio.get(a) === prio.get(b) ? cmp(a, b) : prio.get(a) > prio.get(b) ? -1 : 1))
  const done = new Map()
  const freeAt = Array(workers).fill(0n)
  const runs = Array.from({ length: workers }, () => [])
  let t = 0n
  let left = names.length
  let makespan = 0n
  while (left > 0) {
    for (;;) {
      const w = freeAt.findIndex((f) => f <= t)
      if (w < 0) break
      const task = order.find((u) => !done.has(u) && deps.get(u).every((d) => done.has(d) && done.get(d) <= t))
      if (task === undefined) break
      const f = t + costs.get(task)
      done.set(task, f)
      freeAt[w] = f
      runs[w].push(` ${task}@${t}-${f}`)
      if (f > makespan) makespan = f
      left--
    }
    if (left === 0) break
    let next = null
    for (const f of freeAt) if (f > t && (next === null || f < next)) next = f
    for (const f of done.values()) if (f > t && (next === null || f < next)) next = f
    if (next === null) break
    t = next
  }
  return runs.map((r, i) => `worker ${i}:${r.join('')}\n`).join('') + `makespan ${makespan}\n`
}

function main() {
  const a = process.argv.slice(2)
  const ok = (a.length === 1 && (a[0] === 'waves' || a[0] === 'explain')) || (a.length === 2 && a[0] === 'pack')
  if (!ok) throw new Fail('error: usage: cli.js waves|explain|pack <workers>')
  if (a[0] === 'pack' && !/^[1-9][0-9]*$/.test(a[1])) throw new Fail('error: workers must be a positive integer')
  const g = parse(readFileSync(0, 'utf8'))
  checkCycle(g)
  let out = ''
  if (a[0] === 'pack') {
    out = pack(g, Number(a[1]))
  } else {
    const r = times(g)
    if (a[0] === 'waves') {
      const waves = []
      for (const u of g.names) (waves[r.depth.get(u)] ??= []).push(u)
      waves.forEach((ws, k) => (out += `wave ${k}: ${ws.join(' ')}\n`))
    } else {
      for (const u of g.names) out += `${u} start=${r.start.get(u)} finish=${r.finish.get(u)} depth=${r.depth.get(u)}\n`
    }
    out += `total ${r.total}\n`
  }
  process.stdout.write(out)
}

try {
  main()
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(e.message + '\n')
  process.exitCode = e.code
}
