// Bucket tokens are kept as a numerator over `per`, so fractions stay exact.
function makeState(p, tick) {
  return p.kind === 'bucket'
    ? { num: p.capacity * p.per, last: tick }
    : { ticks: [] }
}

function advance(p, s, tick) {
  if (p.kind === 'bucket') {
    const max = p.capacity * p.per
    s.num += p.refill * (tick - s.last)
    if (s.num > max) s.num = max
    s.last = tick
  } else {
    const cut = tick - p.span
    s.ticks = s.ticks.filter((x) => x > cut)
  }
}

const allows = (p, s) => (p.kind === 'bucket' ? s.num >= p.per : BigInt(s.ticks.length) < p.limit)

function record(p, s, tick) {
  if (p.kind === 'bucket') s.num -= p.per
  else s.ticks.push(tick)
}

export function run({ routes, events }, mode) {
  const prefixes = [...routes.keys()].sort((a, b) => b.length - a.length)
  const states = new Map()
  const stats = new Map()
  const out = []
  let allowed = 0
  let denied = 0
  for (const { tick, key } of events) {
    const prefix = prefixes.find((x) => key.startsWith(x))
    let refused = null
    if (prefix !== undefined) {
      const list = routes.get(prefix)
      const ss = list.map((p) => {
        const id = `${p.name}\n${key}`
        if (!states.has(id)) states.set(id, makeState(p, tick))
        return states.get(id)
      })
      list.forEach((p, i) => advance(p, ss[i], tick))
      const bad = list.findIndex((p, i) => !allows(p, ss[i]))
      if (bad >= 0) refused = list[bad].name
      else list.forEach((p, i) => record(p, ss[i], tick))
    }
    const st = stats.get(key) ?? { a: 0, d: 0 }
    stats.set(key, st)
    if (refused === null) { st.a++; allowed++ } else { st.d++; denied++ }
    out.push(`${tick} ${key} ${refused === null ? 'allow' : `deny ${refused}`}`)
  }
  if (mode === 'replay') return out.map((l) => l + '\n').join('')
  const keys = [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
  return keys.map((k) => `${k} allowed=${stats.get(k).a} denied=${stats.get(k).d}\n`).join('') +
    `total allowed=${allowed} denied=${denied}\n`
}
