import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

class Fail extends Error {}
const NAME = /^[A-Za-z0-9_.\/:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let started = false
  let last = null
  const num = (v, field, least) => {
    if (!INT.test(v) || BigInt(v) < BigInt(least)) throw new Fail(`${field} must be an integer of at least ${least}`)
    return BigInt(v)
  }
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const f = line.split(/\s+/)
    try {
      const d = f[0]
      if (d === 'bucket') {
        if (f.length !== 5) throw new Fail('expected bucket <name> <capacity> <refill> <per>')
        if (started) throw new Fail('declarations must come before the first event')
        if (!NAME.test(f[1])) throw new Fail(`invalid policy name ${f[1]}`)
        const capacity = num(f[2], 'capacity', 1)
        const refill = num(f[3], 'refill', 0)
        const per = num(f[4], 'per', 1)
        if (policies.has(f[1])) throw new Fail(`policy ${f[1]} is declared twice`)
        policies.set(f[1], { kind: 'bucket', name: f[1], capacity, refill, per, state: new Map() })
      } else if (d === 'window') {
        if (f.length !== 4) throw new Fail('expected window <name> <limit> <span>')
        if (started) throw new Fail('declarations must come before the first event')
        if (!NAME.test(f[1])) throw new Fail(`invalid policy name ${f[1]}`)
        const limit = num(f[2], 'limit', 0)
        const span = num(f[3], 'span', 1)
        if (policies.has(f[1])) throw new Fail(`policy ${f[1]} is declared twice`)
        policies.set(f[1], { kind: 'window', name: f[1], limit, span, state: new Map() })
      } else if (d === 'route') {
        if (f.length < 3) throw new Fail('expected route <prefix> <policy>...')
        if (started) throw new Fail('declarations must come before the first event')
        if (!NAME.test(f[1])) throw new Fail(`invalid route prefix ${f[1]}`)
        if (routes.has(f[1])) throw new Fail(`prefix ${f[1]} is routed twice`)
        const ps = f.slice(2).map((n) => {
          if (!policies.has(n)) throw new Fail(`unknown policy ${n}`)
          return policies.get(n)
        })
        routes.set(f[1], ps)
      } else if (d === 'event') {
        if (f.length !== 3) throw new Fail('expected event <tick> <key>')
        const tick = num(f[1], 'tick', 0)
        if (!NAME.test(f[2])) throw new Fail(`invalid key ${f[2]}`)
        if (last !== null && tick < last) throw new Fail(`tick ${tick} is before tick ${last}`)
        last = tick
        started = true
        events.push({ tick, key: f[2] })
      } else {
        throw new Fail(`unknown directive ${d}`)
      }
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${i + 1}: ${e.message}`)
      throw e
    }
  }
  return { routes, events }
}

// Bucket tokens are stored scaled by `per` so fractions stay exact.
function advance(p, key, tick) {
  let s = p.state.get(key)
  if (p.kind === 'bucket') {
    if (!s) {
      s = { tokens: p.capacity * p.per, at: tick }
      p.state.set(key, s)
    } else {
      s.tokens += p.refill * (tick - s.at)
      const max = p.capacity * p.per
      if (s.tokens > max) s.tokens = max
      s.at = tick
    }
  } else {
    if (!s) { s = []; p.state.set(key, s) }
    const cut = tick - p.span
    while (s.length && s[0] <= cut) s.shift()
  }
}
const allows = (p, key) => {
  const s = p.state.get(key)
  return p.kind === 'bucket' ? s.tokens >= p.per : BigInt(s.length) < p.limit
}
function record(p, key, tick) {
  const s = p.state.get(key)
  if (p.kind === 'bucket') s.tokens -= p.per
  else s.push(tick)
}

let result
try {
  result = parse(readFileSync(0, 'utf8'))
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
const { routes, events } = result
const out = []
const counts = new Map()
let ta = 0, td = 0
for (const { tick, key } of events) {
  let best = null
  for (const [prefix, ps] of routes) {
    if (key.startsWith(prefix) && (best === null || prefix.length > best.length)) best = prefix
  }
  let denied = null
  if (best !== null) {
    const ps = routes.get(best)
    for (const p of ps) advance(p, key, tick)
    for (const p of ps) if (!allows(p, key)) { denied = p; break }
    if (!denied) for (const p of ps) record(p, key, tick)
  }
  const c = counts.get(key) || { a: 0, d: 0 }
  if (denied) { c.d++; td++ } else { c.a++; ta++ }
  counts.set(key, c)
  out.push(denied ? `${tick} ${key} deny ${denied.name}` : `${tick} ${key} allow`)
}
if (mode === 'summary') {
  out.length = 0
  for (const k of [...counts.keys()].sort((x, y) => (x < y ? -1 : x > y ? 1 : 0))) out.push(`${k} allowed=${counts.get(k).a} denied=${counts.get(k).d}`)
  out.push(`total allowed=${ta} denied=${td}`)
}
process.stdout.write(out.map((l) => l + '\n').join(''))
