  out.push(`total ${total}`)
} else if (mode === 'explain') {
  for (const x of names) out.push(`${x} start=${start.get(x)} finish=${finish.get(x)} depth=${depth.get(x)}`)
  out.push(`total ${total}`)
} else {
  const dependents = new Map(names.map((x) => [x, []]))
  for (const x of names) for (const v of dl.get(x)) dependents.get(v).push(x)
  const prio = new Map()
  for (let i = topo.length - 1; i >= 0; i--) {
    const u = topo[i]
    let best = 0n
    for (const c of dependents.get(u)) if (prio.get(c) > best) best = prio.get(c)
    prio.set(u, best + cost.get(u))
  }
