      if (w < 0) break
      let pick = null
      for (const x of pending) {
        if (!dl.get(x).every((v) => fin.has(v) && fin.get(v) <= t)) continue
        if (pick === null || prio.get(x) > prio.get(pick) || (prio.get(x) === prio.get(pick) && x < pick)) pick = x
      }
      if (pick === null) break
      pending.delete(pick)
      const f = t + cost.get(pick)
      fin.set(pick, f)
      freeAt[w] = f
      ran[w].push(`${pick}@${t}-${f}`)
      if (f > makespan) makespan = f
    }
    if (!pending.size) break
    let next = null
    for (const f of freeAt) if (f > t && (next === null || f < next)) next = f
    if (next === null) break
    t = next
  }
  ran.forEach((r, i) => out.push(`worker ${i}:` + r.map((s) => ' ' + s).join('')))
  out.push(`makespan ${makespan}`)
}
process.stdout.write(out.join('\n') + '\n')
