        for (;;) {
          if (pred(s[i])) t += adv()
          else if (s[i] === '_' && pred(s[i + 1])) { t += adv(); t += adv() }
          else break
        }
        return true
      }
      const p = s[i + 1]
      const radix = c === '0' ? { x: isHex, X: isHex, b: isBin, B: isBin, o: isOct, O: isOct }[p] : undefined
      if (radix) {
