  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(s)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const L = m[1].toUpperCase()
  const col = L.length === 1 ? L.charCodeAt(0) - 64 : (L.charCodeAt(0) - 64) * 26 + (L.charCodeAt(1) - 64)
  return { col, row }
}

export function colName(c) {
  if (c <= 26) return String.fromCharCode(64 + c)
  return String.fromCharCode(64 + Math.floor((c - 1) / 26)) + String.fromCharCode(65 + ((c - 1) % 26))
}

export function addrKey(a) {
  return colName(a.col) + a.row
}

export function cmpAddr(a, b) {
  return a.col - b.col || a.row - b.row
}
