{"file_path":"src/formula.js","content":"import { parseAddress, cmpAddr, addrKey } from './address.js'

const OPS = ['<>', '<=', '>=', '^', '*', '/', '+', '-', '=', '<', '>', '(', ')', ',', ':']

function tokenize(src) {
  const toks = []
  let i = 0
  while (i < src.length) {
    const ch = src[i]
    if (ch === ' ' || ch === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(src.slice(i)))) {
      toks.push({ k: 'num', v: Number(m[0]) })
      i += m[0].length
    } else if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(src.slice(i)))) {
      toks.push({ k: 'word', v: m[0] })
      i += m[0].length
    } else {
      const op = OPS.find((o) => src.startsWith(o, i))
      if (!op) return null
      toks.push({ k: 'op', v: op })
      i += op.length
    }
  }
  return toks
}

// Returns an AST, or { t: 'bad' } when the grammar rejects the text
// (or a range sits outside a function argument).
export function parseFormula(src) {
  const toks = tokenize(src)
  if (!toks) return { t: 'bad' }
  let p = 0
  let misplaced = false
  const fail = new Error('parse')
  const isOp = (v) => p < toks.length && toks[p].k === 'op' && toks[p].v === v

  function comparison() {
    let l = additive()
    while (p < toks.length && toks[p].k === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: additive() }
    }
    return l
  }
  function additive() {
    let l = term()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: term() }
    }
    return l
  }
  function term() {
    let l = power()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: power() }
    }
    return l
  }
  function power() {
    const l = unary()
    if (isOp('^')) {
      p++
      return { t: 'bin', op: '^', l, r: power() }
    }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { t: 'un', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    if (p >= toks.length) throw fail
    const tk = toks[p]
    if (tk.k === 'num') { p++; return { t: 'num', v: tk.v } }
    if (tk.k === 'op' && tk.v === '(') {
      p++
      const e = comparison()
      if (!isOp(')')) throw fail
      p++
      return e.t === 'range' ? { t: 'paren', e } : e
    }
    if (tk.k !== 'word') throw fail
    p++
    if (isOp('(')) {
      p++
      const args = []
      if (!isOp(')')) {
        for (;;) {
          const a = comparison()
          args.push(a)
          if (isOp(',')) { p++; continue }
          break
        }
      }
      if (!isOp(')')) throw fail
      p++
      return { t: 'call', name: tk.v.toUpperCase(), args }
    }
    if (isOp(':')) {
      p++
      if (p >= toks.length || toks[p].k !== 'word') throw fail
      const w2 = toks[p++].v
      if (isOp('(')) throw fail
      return { t: 'range', a: parseAddress(tk.v), b: parseAddress(w2) }
    }
    const up = tk.v.toUpperCase()
    if (up === 'TRUE') return { t: 'bool', v: true }
    if (up === 'FALSE') return { t: 'bool', v: false }
    return { t: 'ref', a: parseAddress(tk.v) }
  }

  let ast
  try {
    ast = comparison()
    if (p !== toks.length) return { t: 'bad' }
  } catch (e) {
    if (e === fail) return { t: 'bad' }
    throw e
  }
  if (!rangesOk(ast, false)) misplaced = true
  if (misplaced) return { t: 'bad', refs: ast }
  return ast
}

function rangesOk(n, asArg) {
  switch (n.t) {
    case 'range': return asArg
    case 'bin': return rangesOk(n.l, false) && rangesOk(n.r, false)
    case 'un': return rangesOk(n.e, false)
    case 'paren': return false
    case 'call': return n.args.every((a) => rangesOk(a, true))
    default: return true
  }
}

export function collectDeps(ast) {
  const set = new Map()
  const add = (a) => { if (a) set.set(addrKey(a), a) }
  const walk = (n) => {
    switch (n.t) {
      case 'ref': add(n.a); break
      case 'range':
        if (n.a && n.b) {
          const c1 = Math.min(n.a.col, n.b.col), c2 = Math.max(n.a.col, n.b.col)
          const r1 = Math.min(n.a.row, n.b.row), r2 = Math.max(n.a.row, n.b.row)
          for (let c = c1; c <= c2; c++) for (let r = r1; r <= r2; r++) add({ col: c, row: r })
        }
        break
      case 'bin': walk(n.l); walk(n.r); break
      case 'un': case 'paren': walk(n.e); break
      case 'call': n.args.forEach(walk); break
      case 'bad': if (n.refs) walk(n.refs); break
    }
  }
  walk(ast)
  return [...set.values()].sort(cmpAddr)
}
"}

{"file_path":"src/eval.js","content":"import { addrKey } from './address.js'

const ERRS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const err = (v) => ({ t: 'err', v })
const num = (v) => ({ t: 'num', v })
const ZERO = num(0)

function literal(content) {
  if (content === '') return ZERO
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return num(Number(content))
  if (ERRS.includes(content)) return err(content)
  return { t: 'text', v: content }
}

function toNum(v) {
  if (v.t === 'num') return v
  if (v.t === 'bool') return num(v.v ? 1 : 0)
  return err('#VALUE!')
}

function finite(x) {
  return Number.isFinite(x) ? num(x) : err('#DIV/0!')
}

function cmpStr(a, b) {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  for (let i = 0; i < Math.min(x.length, y.length); i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}

const RANK = { num: 0, text: 1, bool: 2 }
function compare(a, b) {
  if (a.t !== b.t) return RANK[a.t] - RANK[b.t]
  if (a.t === 'text') return cmpStr(a.v, b.v)
  const x = Number(a.v), y = Number(b.v)
  return x < y ? -1 : x > y ? 1 : 0
}

export function evaluateAll(cells) {
  const memo = new Map()
  const busy = new Set()

  function cellValue(a) {
    if (!a) return err('#REF!')
    const k = addrKey(a)
    if (memo.has(k)) return memo.get(k)
    const c = cells.get(k)
    if (!c) return ZERO
    if (busy.has(k)) return err('#CYCLE!')
    busy.add(k)
    let v
    if (!c.ast) v = literal(c.content)
    else if (c.ast.t === 'bad') v = err('#ERR!')
    else v = ev(c.ast)
    busy.delete(k)
    memo.set(k, v)
    return v
  }

  function expand(r) {
    if (!r.a || !r.b) return [err('#REF!')]
    const out = []
    const c1 = Math.min(r.a.col, r.b.col), c2 = Math.max(r.a.col, r.b.col)
    const r1 = Math.min(r.a.row, r.b.row), r2 = Math.max(r.a.row, r.b.row)
    for (let c = c1; c <= c2; c++) for (let w = r1; w <= r2; w++) out.push(cellValue({ col: c, row: w }))
    return out
  }

  function ev(n) {
    switch (n.t) {
      case 'num': return num(n.v)
      case 'bool': return { t: 'bool', v: n.v }
      case 'ref': return cellValue(n.a)
      case 'range': case 'paren': return err('#ERR!')
      case 'un': {
        const v = ev(n.e)
        if (v.t === 'err') return v
        const x = toNum(v)
        if (x.t === 'err') return x
        return n.op === '-' ? num(-x.v) : x
      }
      case 'bin': {
        const l = ev(n.l)
        const r = ev(n.r)
        if (l.t === 'err') return l
        if (r.t === 'err') return r
        if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
          const c = compare(l, r)
          const res = { '=': c === 0, '<>': c !== 0, '<': c < 0, '<=': c <= 0, '>': c > 0, '>=': c >= 0 }[n.op]
          return { t: 'bool', v: res }
        }
        const x = toNum(l)
        if (x.t === 'err') return x
        const y = toNum(r)
        if (y.t === 'err') return y
        switch (n.op) {
          case '+': return finite(x.v + y.v)
          case '-': return finite(x.v - y.v)
          case '*': return finite(x.v * y.v)
          case '/': return y.v === 0 ? err('#DIV/0!') : finite(x.v / y.v)
          default: return finite(Math.pow(x.v, y.v))
        }
      }
      case 'call': return call(n)
    }
    return err('#ERR!')
  }

  function call(n) {
    const name = n.name
    const argc = n.args.length
    if (name === 'IF') {
      if (argc !== 3) return err('#ERR!')
      if (n.args.some((a) => a.t === 'range')) return err('#VALUE!')
      const c = ev(n.args[0])
      if (c.t === 'err') return c
      let truth
      if (c.t === 'bool') truth = c.v
      else if (c.t === 'num') truth = c.v !== 0
      else return err('#VALUE!')
      return ev(truth ? n.args[1] : n.args[2])
    }
    if (name === 'ABS') {
      if (argc !== 1) return err('#ERR!')
      if (n.args[0].t === 'range') return err('#VALUE!')
      const v = ev(n.args[0])
      if (v.t === 'err') return v
      const x = toNum(v)
      return x.t === 'err' ? x : num(Math.abs(x.v))
    }
    if (!['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(name)) return err('#NAME?')
    if (argc < 1) return err('#ERR!')
    const vals = []
    for (const a of n.args) {
      if (a.t === 'range') vals.push(...expand(a))
      else vals.push(ev(a))
    }
    const e = vals.find((v) => v.t === 'err')
    if (e) return e
    if (name === 'COUNT') return num(vals.filter((v) => v.t === 'num').length)
    const nums = []
    for (const v of vals) {
      const x = toNum(v)
      if (x.t === 'err') return x
      nums.push(x.v)
    }
    switch (name) {
      case 'SUM': return finite(nums.reduce((s, x) => s + x, 0))
      case 'MIN': return num(Math.min(...nums))
      case 'MAX': return num(Math.max(...nums))
      default: return finite(nums.reduce((s, x) => s + x, 0) / nums.length)
    }
  }

  return (k) => cellValue(cells.get(k).addr)
}
"}

