{"file_path":"src/cli.js","content":"import { readFileSync } from 'node:fs'
import { parseFormula, collectDeps } from './formula.js'
import { evaluateAll } from './eval.js'
import { parseAddress, addrKey, cmpAddr } from './address.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'values' && mode !== 'deps') {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cells = new Map()
for (let i = 0; i < lines.length; i++) {
  const s = lines[i].replace(/^[ \t]+/, '')
  if (s === '' || s[0] === '#') continue
  const token = /^[^ \t]*/.exec(s)[0]
  const addr = parseAddress(token.toUpperCase())
  if (!addr) {
    process.stderr.write(`error: line ${i + 1}: invalid cell address ${token}\n`)
    process.exit(2)
  }
  const key = addrKey(addr)
  if (cells.has(key)) {
    process.stderr.write(`error: line ${i + 1}: cell ${key} is declared twice\n`)
    process.exit(2)
  }
  const content = s.slice(token.length).replace(/^[ \t]+/, '')
  cells.set(key, { addr, content, ast: content[0] === '=' ? parseFormula(content.slice(1)) : null })
}

const sorted = [...cells.values()].sort((a, b) => cmpAddr(a.addr, b.addr))
let out = ''
if (mode === 'deps') {
  for (const c of sorted) {
    const deps = c.ast ? collectDeps(c.ast) : []
    out += `${addrKey(c.addr)}:` + deps.map((d) => ' ' + addrKey(d)).join('') + '\n'
  }
} else {
  const vals = evaluateAll(cells)
  for (const c of sorted) {
    const k = addrKey(c.addr)
    const v = vals(k)
    let text
    if (v.t === 'num') text = String(Number(v.v.toPrecision(10)))
    else if (v.t === 'bool') text = v.v ? 'TRUE' : 'FALSE'
    else text = v.v
    out += `${k}=${text}\n`
  }
}
process.stdout.write(out)
"}

