export function parse(s) {
  const r = { scheme: undefined, authority: undefined, path: '', query: undefined, fragment: undefined }
  const m = /^([^:/?#]+):/.exec(s)
  if (m) { r.scheme = m[1]; s = s.slice(m[0].length) }
  if (s.startsWith('//')) {
    const e = s.slice(2).search(/[/?#]/)
    if (e < 0) { r.authority = s.slice(2); s = '' } else { r.authority = s.slice(2, 2 + e); s = s.slice(2 + e) }
  }
  const h = s.indexOf('#')
  if (h >= 0) { r.fragment = s.slice(h + 1); s = s.slice(0, h) }
  const q = s.indexOf('?')
  if (q >= 0) { r.query = s.slice(q + 1); s = s.slice(0, q) }
  r.path = s
  return r
}

export function removeDots(path) {
  let inp = path, out = ''
  while (inp.length) {
    if (inp.startsWith('../')) inp = inp.slice(3)
    else if (inp.startsWith('./')) inp = inp.slice(2)
    else if (inp.startsWith('/./')) inp = inp.slice(2)
    else if (inp === '/.') inp = '/'
    else if (inp.startsWith('/../') || inp === '/..') {
      inp = inp === '/..' ? '/' : inp.slice(3)
      out = out.slice(0, Math.max(0, out.lastIndexOf('/')))
    } else if (inp === '.' || inp === '..') inp = ''
    else {
      const i = inp.indexOf('/', 1)
      const seg = i < 0 ? inp : inp.slice(0, i)
      out += seg
      inp = inp.slice(seg.length)
    }
  }
  return out
}

function splitAuthority(a) {
  const at = a.lastIndexOf('@')
  const userinfo = at >= 0 ? a.slice(0, at) : undefined
  const rest = a.slice(at + 1)
  const from = rest.lastIndexOf(']') + 1
  const c = rest.indexOf(':', from)
  if (c < 0) return { userinfo, host: rest, port: undefined }
  return { userinfo, host: rest.slice(0, c), port: rest.slice(c + 1) }
}

const lower = (s) => s.replace(/[A-Z]+/g, (x) => x.toLowerCase())
const UNRES = /^[A-Za-z0-9\-._~]$/
function pct(s) {
  return s.replace(/%([0-9a-fA-F]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return UNRES.test(c) ? c : '%' + h.toUpperCase()
  })
}
const bad = (s) => s !== undefined && /%(?![0-9a-fA-F]{2})/.test(s)
const DEFAULTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

export function normalize(r, lineNo) {
  const au = r.authority === undefined ? undefined : splitAuthority(r.authority)
  const checks = [['path', r.path], ['userinfo', au?.userinfo], ['host', au?.host], ['query', r.query], ['fragment', r.fragment]]
  for (const [n, v] of checks) {
    if (bad(v)) throw new Error(`line ${lineNo}: the ${n} has a truncated percent-encoding`)
  }
  const scheme = r.scheme === undefined ? undefined : lower(r.scheme)
  let out = ''
  if (scheme !== undefined) out += scheme + ':'
  let path = pct(r.path)
  if (au) {
    let a = ''
    if (au.userinfo !== undefined) a += pct(au.userinfo) + '@'
    a += lower(pct(au.host))
    let port = au.port
    if (port === '' || (scheme !== undefined && DEFAULTS[scheme] === port)) port = undefined
    if (port !== undefined) a += ':' + port
    out += '//' + a
  }
  path = removeDots(path)
  if (au && path === '') path = '/'
  out += path
  if (r.query !== undefined) out += '?' + pct(r.query)
  if (r.fragment !== undefined) out += '#' + pct(r.fragment)
  return out
}

export function resolve(base, ref) {
  const t = {}
  if (ref.scheme !== undefined) {
    Object.assign(t, ref, { path: removeDots(ref.path) })
  } else if (ref.authority !== undefined) {
    Object.assign(t, ref, { scheme: base.scheme, path: removeDots(ref.path) })
  } else {
    t.scheme = base.scheme
    t.authority = base.authority
    t.fragment = ref.fragment
    if (ref.path === '') {
      t.path = base.path
      t.query = ref.query !== undefined ? ref.query : base.query
    } else {
      t.query = ref.query
      let p = ref.path
      if (!p.startsWith('/')) {
        if (base.authority !== undefined && base.path === '') p = '/' + p
        else {
          const i = base.path.lastIndexOf('/')
          p = i >= 0 ? base.path.slice(0, i + 1) + p : p
        }
      }
      t.path = removeDots(p)
    }
  }
  return t
}
