import { readFileSync } from 'node:fs'

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'rounds' && args[0] !== 'tally')) fail('error: usage: cli.js rounds|tally')
const mode = args[0]

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

let cands = null
const ballots = []
const declErr = n => `error: line ${n}: candidates must be declared once, before any ballot`
for (let i = 0; i < lines.length; i++) {
  const n = i + 1
  const t = lines[i].trim()
  if (t === '' || t.startsWith('#')) continue
  const w = t.split(/\s+/)
  if (w[0] === 'candidates') {
    if (cands !== null || ballots.length) fail(declErr(n))
    if (w.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
    const seen = new Set()
    for (const name of w.slice(1)) {
      if (!/^[A-Za-z0-9_-]+$/.test(name)) fail(`error: line ${n}: invalid candidate name ${name}`)
      if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is declared twice`)
      seen.add(name)
    }
    cands = w.slice(1)
  } else if (w[0] === 'ballot') {
    if (cands === null) fail(declErr(n))
    if (w.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
    if (!/^[1-9][0-9]*$/.test(w[1])) fail(`error: line ${n}: count must be a positive integer`)
    const seen = new Set()
    for (const name of w.slice(2)) {
      if (!cands.includes(name)) fail(`error: line ${n}: unknown candidate ${name}`)
      if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is repeated`)
      seen.add(name)
    }
    ballots.push({ count: BigInt(w[1]), prefs: w.slice(2) })
  } else {
    fail(`error: line ${n}: unknown directive ${w[0]}`)
  }
}
if (cands === null) fail('error: no candidates')

const alive = new Set(cands)
const hist = new Map(cands.map(c => [c, []]))
const out = []
let round = 0
let result
for (;;) {
  round++
  const counts = new Map([...alive].map(c => [c, 0n]))
  let active = 0n
  for (const b of ballots) {
    const c = b.prefs.find(p => alive.has(p))
    if (c !== undefined) { counts.set(c, counts.get(c) + b.count); active += b.count }
  }
  let total = 0n
  for (const b of ballots) total += b.count
  for (const [c, v] of counts) hist.get(c).push(v)
  const order = [...counts.keys()].sort((a, b) => counts.get(a) > counts.get(b) ? -1 : counts.get(a) < counts.get(b) ? 1 : a < b ? -1 : a > b ? 1 : 0)
  out.push(`round ${round}: ${order.map(c => `${c}=${counts.get(c)}`).join(' ')} exhausted=${total - active}`)
  if (active === 0n) { result = 'no winner'; break }
  const win = order.find(c => counts.get(c) * 2n > active)
  if (win !== undefined) { result = `winner ${win}`; break }
  let min = null
  for (const v of counts.values()) if (min === null || v < min) min = v
  let tied = [...alive].filter(c => counts.get(c) === min)
  for (let r = 0; r < round && tied.length > 1; r++) {
    let lo = null, differ = false
    for (const c of tied) {
      const v = hist.get(c)[r]
      if (lo !== null && v !== lo) differ = true
      if (lo === null || v < lo) lo = v
    }
    if (differ) { tied = tied.filter(c => hist.get(c)[r] === lo); r = -1 }
  }
  tied.sort()
  const elim = tied[tied.length - 1]
  alive.delete(elim)
  out.push(`eliminated ${elim}`)
}
out.push(result)
process.stdout.write((mode === 'tally' ? [`rounds ${round}`, result] : out).join('\n') + '\n')
EOF
